  t.innerHTML=`<div class="t-avatar" style="background:${(opts.avatarUrl&&String(opts.avatarUrl).startsWith('data:'))?'transparent':(opts.color||'#7c3aed')}">${avaHtml}</div><div class="t-body"><div class="t-title">${esc(opts.title||'New message')}</div><div class="t-text">${esc(opts.body||'')}</div></div>`;
