window.acceptVoiceCall=acceptVoiceCall;
window.rejectVoiceCall=rejectVoiceCall;
window.endVoiceCall=endVoiceCall;
window.toggleMute=toggleMute;
window.toggleSpeaker=toggleSpeaker;

