// Local mode: onno tab e message dile ei tab e notification (Firebase off thakle)
window.addEventListener('storage',(e)=>{
  if(e.key!=='chatbd_global_rooms'||!currentUserData) return;
  if(currentUserData.firebase===true) return; // Firebase user ra rooms listener theke receipt pay
  try{
    const rooms=getGlobalRooms();
    Object.values(rooms).forEach(room=>{
      if(!(room.participants||[]).includes(currentUserData.username)) return;
      const sig=(room.lastTime||'')+'|'+(room.lastMessage||'');
      if(prevRoomSig[room.id] && prevRoomSig[room.id]!==sig){
        const lastMsg=(room.messages||[])[room.messages.length-1];
        const fromMe=lastMsg&&lastMsg.sender===currentUserData.username;
        if(!fromMe){
          const isOpenVisible=(currentRoomId===room.id && !document.hidden);
          const skipTexts=['New conversation','Cleared'];
          // ✓✓ amar tab/device delivered peyeche marker
          try{room['lastDeliveredAt_'+currentUserData.username]=Date.now(); saveGlobalRooms(rooms);}catch(e){}
          if(!isOpenVisible && room.lastMessage && !skipTexts.includes(room.lastMessage)){
            const other=room.participants.find(p=>p!==currentUserData.username);
            const od=getUsers()[other]||{};
            notifyIncomingMessage({roomId:room.id,title:od.nickname||other||'New message',body:String(room.lastMessage||'').slice(0,90),color:od.color||'#7c3aed',avatar:String(od.nickname||other||'U').slice(0,2).toUpperCase(),avatarUrl:od.avatarUrl||null,senderUsername:other});
            if(currentRoomId!==room.id) bumpUnread(room.id);
          }
        }
      }
      prevRoomSig[room.id]=sig;
      // ✓✓ marker/content jekono change e khola chat re-render (ticks update)
      if(currentRoomId===room.id) renderMessagesForRoom(room.id, false);
    });
    contacts=loadUserContacts(currentUserData.username);
    renderChats();
  }catch(err){}
});

